interface package paperI

package Example
  uniontype Statement  "Algorithmic stmts"
    record ASSIGN  "An assignment stmt"
      Exp lhs; Exp rhs;
    end ASSIGN;

    record WHILE  "A while statement"
      Exp condition;
      list<Statement> statements;
    end WHILE;
  end Statement;

  uniontype Exp  "Expression nodes"
    record ICONST  "Integer constant value"
      Integer value;
    end ICONST;

    record VARIABLE "Variable reference"
      String name;
    end VARIABLE;

    record BINARY  "Binary ops"
      Exp lhs;
      Operator op;
      Exp rhs;
    end BINARY;
  end Exp;

package paper

public import Tpl;

public import Example;

protected function lm_1
  input Tpl.Text in_txt;
  input list<Example.Statement> in_items;

  output Tpl.Text out_txt;
algorithm
  out_txt :=
  matchcontinue(in_txt, in_items)
    local
      Tpl.Text txt;

    case ( txt,
           {} )
      then txt;

    case ( txt,
           i_it :: rest )
      local
        list<Example.Statement> rest;
        Example.Statement i_it;
      equation
        txt = statement(txt, i_it);
        txt = Tpl.nextIter(txt);
        txt = lm_1(txt, rest);

