// Circle model

model Circle
  Real x_out;
  Real y_out;
  Real x(start=0.1);
  Real y(start=0.1);
equation
  der(x) = y;
  der(y) = x;
  x_out = x;
  y_out = y;
end Circle;

model dcmotor
  import Modelica.Electrical.Analog.Basic;
  Basic.Resistor resistor1(R = 10);
  Basic.Inductor inductor1(L = 0.2, i.fixed=true);
  Basic.Ground ground1;
  Modelica.Mechanics.Rotational.Components.Inertia load(J = 1, phi.fixed=true, w.fixed=true);
  Basic.EMF emf1(k=1.0);
  Modelica.Blocks.Sources.Step step1;
  Modelica.Electrical.Analog.Sources.SignalVoltage signalVoltage1;
equation
  connect(step1.y, signalVoltage1.v);
  connect(signalVoltage1.p, resistor1.p);
  connect(resistor1.n, inductor1.p);
  connect(inductor1.n, emf1.p);
  connect(emf1.flange, load.flange_a);
  connect(signalVoltage1.n, ground1.p);
  connect(ground1.p, emf1.n);
  annotation(uses(Modelica(version="3.2.2")));
end dcmotor;

within ;
package Debugging "Test cases for debugging of declarative models"

  package Chattering "Models with chattering behaviour"
    model ChatteringEvents1
      "Exhibits chattering after t = 0.5, with generated events"
      Real x(start=1, fixed=true);
      Real y;
      Real z;
    equation
      z = if x > 0 then -1 else 1;
      y = 2*z;
      der(x) = y;
      annotation (Documentation(info="<html>
<p>After t = 0.5, chattering takes place, due to the discontinuity in the right hand side of the first equation.</p>
<p>Chattering can be detected because lots of tightly spaced events are generated. The feedback to the user should allow to identify the equation from which the zero crossing function that generates the events originates.</p>
</html>"), experiment(StopTime=1));
    end ChatteringEvents1;

    model ChatteringEvents2
      "Exhibits chattering after t = 0.422, with generated events"
      Real x(start=1, fixed=true);
      Real w(start=0, fixed=true);
      Real y;
      Real z;
    equation
      der(w) = -w + 1;
      z = if x > 0 then -1 else 1;
      y = 2*(z - w);
      der(x) = y;

double ExternalFunc1_ext(double x)
{
  double res;

  res = x+2.0*x*x;
  return res;
}

double ExternalFunc2(double x)

{
  double res;
  res = (x-1.0)*(x+2.0);
  return res;
}

function ExternalFunc1
  input Real x;
  output Real y;
  external y=ExternalFunc1_ext(x) annotation(Library="libExternalFunc1_ext.o",Include="#include \"ExternalFunc1_ext.h\"");
end ExternalFunc1;

function ExternalFunc2
  input Real x;
  output Real y;
  external "C" annotation(Library="libExternalFunc2.a",Include="#include \"ExternalFunc2.h\"");
end ExternalFunc2;


model ExternalLibraries

  Real x(start=1.0),y(start=2.0);
equation
der(x)=-ExternalFunc1(x);
der(y)=-ExternalFunc2(y);
end ExternalLibraries;

class HelloWorld
  Real x(start = 1);
  parameter Real a = 1;
equation
  der(x) = - a * x;
end HelloWorld;

// Influenza model

connector Port = Real;

model Population
  input Port in_1;
  input Port in_2;
  output Port out_1;
  output Real p(start=10);
equation
  der(p)=in_1 - in_2;
  out_1 = p;
end Population;


model Division
  input Port in_1;
  input Port in_2;
  output Port out_1;
  parameter Real c=1.00;
equation
  out_1 = c*in_1/in_2;
end Division;


model Constants
  output Port out_1;
  parameter Real c=1.0;
equation
  out_1 = c;

// A simple integrator example.
//

model SimpleIntegrator
  Real u = 1.0;
  Real x(start = 2.0);
equation
  der(x) = u;
end SimpleIntegrator;

model Switch
  Real v;
  Real i;
  Real i1;
  Real itot;
  Boolean open;
equation
  itot = i + i1;
  if open then
    v = 0;
  else
    i = 0;
  end if;
   1 - i1 = 0;
   1 - v - i = 0;
   open = time >= 0.5;
end Switch;

// Van der Pol model

model VanDerPol  "Van der Pol oscillator model"
  Real x(start = 1, fixed = true);
  Real y(start = 1, fixed = true);
  parameter Real lambda = 0.3;
equation
  der(x) = y;
  der(y) = - x + lambda*(1 - x*x)*y;
end VanDerPol;

model BouncingBall3D
  import SimpleVisual;
  parameter Real e=0.7 "coefficient of restitution";
  parameter Real g=9.81 "gravity acceleration";
  Real h(start=10) "height of ball";
  Real v "velocity of ball";
  Boolean flying(start=true) "true, if ball is flying";
  Boolean impact;
  Real v_new;
  SimpleVisual.PositionSize obj "color=blue;shape=sphere;";
equation
  impact= h < 0.0;
  der(v)=if flying then -g else 0;
  der(h)=v;

  obj.size[1]=5;
  obj.size[2]=5;
  obj.size[3]=5;
  obj.frame_a[1]=0;
  obj.frame_a[2]=h+obj.size[2]/2;
  obj.frame_a[3]=0;

  when {h <= 0.0 and v <= 0.0,impact} then
    v_new=if edge(impact) then -e*pre(v) else 0;
    flying=v_new > 0;
    reinit(v, v_new);
  end when;
end BouncingBall3D;

