std::string Arrays::listToString(const std::vector<std::string> &list, const std::string &separator)
{
  std::stringstream ss;
  bool firstEntry = true;

  ss << '[';
  for (auto &entry : list) {
    ss << entry;
    if (firstEntry) {
      ss << separator;
      firstEntry = false;
    }
  }

  ss << ']';
  return ss.str();
}

